import{_ as t,o as a,c as u,ag as e}from"./chunks/framework.B5ULsuav.js";const k=JSON.parse('{"title":"丹道金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-丹道.md","filePath":"40-原话金句/quote-丹道.md","lastUpdated":1778155802000}'),r={name:"40-原话金句/quote-丹道.md"};function q(s,o,l,n,i,c){return a(),u("div",null,[...o[0]||(o[0]=[e('<h1 id="丹道金句" tabindex="-1">丹道金句 <a class="header-anchor" href="#丹道金句" aria-label="Permalink to &quot;丹道金句&quot;">​</a></h1><blockquote><p>了空居士关于丹道修炼、静坐、站桩、功夫层次的精彩原话集 含：顿超法门、神守黄房、似守非守、师力加持、气感与境界</p></blockquote><hr><h2 id="一、丹道总纲" tabindex="-1">一、丹道总纲 <a class="header-anchor" href="#一、丹道总纲" aria-label="Permalink to &quot;一、丹道总纲&quot;">​</a></h2><blockquote><p><strong>&quot;养气忘言守，降心为不为。动静知宗祖，无事更寻谁。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/中论丹道-养气忘言守">中论丹道-养气忘言守</a>（吕祖《百字碑》，了空居士顿超法门总纲）</p></blockquote><blockquote><p><strong>&quot;功法和门派虽然很多，但确是殊途同归。入门的方法千差万别，练到气通大周天之后，基本上都是无为的；等到气通中脉之后根本就没有什么特定的功法了。&quot;</strong> ——论坛语录</p></blockquote><blockquote><p><strong>&quot;聚气是有为法，是我执，跟大自然能量场不沟通。贯穿我们身体内外的混元气场不是我们练出来的，而是我们融进去的。&quot;</strong> ——答疑专辑2019_修炼篇</p></blockquote><hr><h2 id="二、下手功夫" tabindex="-1">二、下手功夫 <a class="header-anchor" href="#二、下手功夫" aria-label="Permalink to &quot;二、下手功夫&quot;">​</a></h2><blockquote><p><strong>&quot;神守黄房，金胎自成。黄房乃乾之下、坤之上。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p></blockquote><blockquote><p><strong>&quot;不可用心守，不可无意求。用心守则着相，无意求则落空。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p></blockquote><blockquote><p><strong>&quot;似守非守——守得太紧就着相，守得太松就无效。要在有心无心之间。轻轻知道，轻轻放下。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p></blockquote><blockquote><p><strong>&quot;行住坐卧，绵绵若存。不是只有打坐时才观照，而是随时保持一种轻轻返观身体的状态。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p></blockquote><hr><h2 id="三、顿超法门" tabindex="-1">三、顿超法门 <a class="header-anchor" href="#三、顿超法门" aria-label="Permalink to &quot;三、顿超法门&quot;">​</a></h2><blockquote><p><strong>&quot;我师父当年是以师力加持的，就连意守下丹田都不用，刹那间就通大周天了。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/中论丹道-师力加持">中论丹道-师力加持</a></p></blockquote><blockquote><p><strong>&quot;师力加持其实就是能量的共振，通过共振你融进了师父的气场，使你进入了高的层次。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/中论丹道-师力加持">中论丹道-师力加持</a></p></blockquote><blockquote><p><strong>&quot;你们跟我学的，我是以顿超法门师力加持，就不用搞那些采气了。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/中论丹道-师力加持">中论丹道-师力加持</a></p></blockquote><blockquote><p><strong>&quot;但安神息，不运火而火自运——只要你心平气和，火候就恰到好处，自然运行。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p></blockquote><hr><h2 id="四、气感与境界" tabindex="-1">四、气感与境界 <a class="header-anchor" href="#四、气感与境界" aria-label="Permalink to &quot;四、气感与境界&quot;">​</a></h2><blockquote><p><strong>&quot;有境界不执着，没有境界不着急。每个人因缘不同。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;不要追求境界，境界自然会来。你越是追，它越是跑。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;修行的目的是明心见性，不是神通。神通是副产品，不需要追求，也拒绝显摆。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;万法平等在果——不同的方法都能到彼岸，只是速度不同。你坐飞机我不轻视走路的人，走路的人也不要笑话我贪图方便。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/答疑2014-万法平等在果">答疑2014-万法平等在果</a></p></blockquote><hr><h2 id="五、修炼原理" tabindex="-1">五、修炼原理 <a class="header-anchor" href="#五、修炼原理" aria-label="Permalink to &quot;五、修炼原理&quot;">​</a></h2><blockquote><p><strong>&quot;宇宙的能量场有无穷无尽的频道，我们通过修行慢慢与更多的场同步共振。通过意守，身心慢慢放松，就跟我们同步共振的场越来越多。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/虚无中的共振-能量共振">虚无中的共振-能量共振</a></p></blockquote><blockquote><p><strong>&quot;先天元神元炁，刻刻相合，渐渐相化。元神和元炁不是割裂的，而是二而一的。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p></blockquote><blockquote><p><strong>&quot;身体虚无，精神状态好，二者俱佳——这就是形神俱妙。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p></blockquote><blockquote><p><strong>&quot;道家是以增强内气从而增强外场；佛家多数是增强外场而增强内气。修炼的最高境界就是亲证实相，以现代的言语来说，就是零维。&quot;</strong> ——论坛语录</p></blockquote><hr><h2 id="六、实修要诀" tabindex="-1">六、实修要诀 <a class="header-anchor" href="#六、实修要诀" aria-label="Permalink to &quot;六、实修要诀&quot;">​</a></h2><blockquote><p><strong>&quot;练功的姿势无论行住坐卧都可以——摆好一定的姿势，意念轻轻观察身体，同时轻轻观察自己的念头。&quot;</strong> ——答疑专辑</p></blockquote><blockquote><p><strong>&quot;静坐时杂念来了，看着它，不跟随，不攀缘，它自然就消失了。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;跟你讲得最简单：你轻轻返观中丹田，不要意守下丹田，不要搞什么采气。&quot;</strong> ——中论丹道</p></blockquote><hr><h2 id="七、常见误区" tabindex="-1">七、常见误区 <a class="header-anchor" href="#七、常见误区" aria-label="Permalink to &quot;七、常见误区&quot;">​</a></h2><blockquote><p><strong>&quot;不要追求感觉——发热、发麻都是正常，没有也正常。功夫到了自然有，不到不强求。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;入静并不是说一念不生。一个念头都没有，那个大脑是有问题的。&quot;</strong> ——答疑专辑2019_修炼篇</p></blockquote><blockquote><p><strong>&quot;百日功夫，必有变化——但这不是按天数计算的。顿法入门快，可能刹那间通大周天。但深入仍需持续。&quot;</strong> ——五篇灵文</p></blockquote><hr><h2 id="简短金句" tabindex="-1">简短金句 <a class="header-anchor" href="#简短金句" aria-label="Permalink to &quot;简短金句&quot;">​</a></h2><blockquote><p>&quot;似守非守。&quot; &quot;绵绵若存。&quot; &quot;不追不求。&quot; &quot;自然呼吸。&quot; &quot;轻轻知道。&quot;</p></blockquote><hr><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/中论丹道_了空居士_完整版(全83篇)">中论丹道_了空居士_完整版(全83篇)</a>、<a href="/liaokongjushi-wisdom/01-Raw-Sources/五篇灵文_了空居士_完整版">五篇灵文_了空居士_完整版</a>、答疑专辑2014练功、答疑专辑2019修炼篇、论坛语录、虚无中的共振 整理日期：2026-05-06 | 重构：2026-05-07（新增顿超法门、修炼原理、常见误区金句15+条；按丹道主题重组）</p></blockquote>',46)])])}const b=t(r,[["render",q]]);export{k as __pageData,b as default};
